int main(int argc, char** argv) {
    std::cout << std::setprecision(17);
    long iters = argc > 1 ? std::atol(argv[1]) : 1;
    long warmup = argc > 2 ? std::atol(argv[2]) : 0;

    // Input node 'x'
    std::vector<double> v_x(64);
    for (int i = 0; i < 64; ++i) {
        if (!(std::cin >> v_x[i])) {
            std::cerr << "Error: failed to read input value " << i << " for node \"x\" (expected 64 doubles)" << std::endl;
            return 1;
        }
    }

    // FusedLinearReLU node 'a0'
    std::vector<double> v_a0(32);

    // Linear node 'logits'
    std::vector<double> v_logits(10);

    double checksum = 0.0;

    auto compute = [&]() {
        // FusedLinearReLU node 'a0'
    for (int j = 0; j < 32; ++j) {
        double acc = v_a0_b[j];
        for (int i = 0; i < 64; ++i) {
            acc += v_x[i] * v_a0_w[i * 32 + j];
        }
        v_a0[j] = std::max(0.0, acc);
    }

        // Linear node 'logits'
    for (int j = 0; j < 10; ++j) {
        double acc = v_logits_b[j];
        for (int i = 0; i < 32; ++i) {
            acc += v_a0[i] * v_logits_w[i * 10 + j];
        }
        v_logits[j] = acc;
    }

    };

    for (long rep = 0; rep < warmup; ++rep) {
        compute();
    }

    auto tinynn_bench_start = std::chrono::steady_clock::now();
    for (long rep = 0; rep < iters; ++rep) {
        compute();
        checksum += v_logits.empty() ? 0.0 : v_logits.back();
    }
    auto tinynn_bench_end = std::chrono::steady_clock::now();

    // print output node 'logits'
    for (size_t i = 0; i < v_logits.size(); ++i) {
        if (i) std::cout << " ";
        std::cout << v_logits[i];
    }
    std::cout << "\n";

    if (iters > 1) {
        long long tinynn_bench_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(tinynn_bench_end - tinynn_bench_start).count();
        std::cerr << "BENCH_NS " << tinynn_bench_ns << " CHECKSUM " << std::setprecision(17) << checksum << std::endl;
    }

    return 0;
}
